package com.ruoyi.medical.persistence;
import com.fasterxml.jackson.databind.JsonNode;import com.ruoyi.medical.contracts.*;import java.util.*;import javax.sql.DataSource;import org.springframework.jdbc.core.JdbcTemplate;
/** Revalidates the exact registered verification inputs. A private proof is limited to this admission and fixed job. */
public final class FormalInvocationCurrent {
 private final ModelConfigurationService models;private final FormalCapabilityIdentityAuthority capabilities;private final FormalInvocationRules rules;private final FormalInvocationInputs inputs;private final FormalInvocationSourceOriginals originals;private final ResourceReadAuthority resources;private final ApprovedCredentialAuthority credentials;private final FormalInvocationSchema schema;private final JdbcTemplate db;
 public FormalInvocationCurrent(ModelConfigurationService models,FormalCapabilityIdentityAuthority capabilities,FormalInvocationRules rules,FormalInvocationInputs inputs,FormalInvocationSourceOriginals originals,ResourceReadAuthority resources,ApprovedCredentialAuthority credentials,FormalInvocationSchema schema,DataSource data){this.models=models;this.capabilities=capabilities;this.rules=rules;this.inputs=inputs;this.originals=originals;this.resources=resources;this.credentials=credentials;this.schema=schema;db=new JdbcTemplate(data);db.setQueryTimeout(5);}
 public final class Verified {
  private final EnterpriseAccess.Admission admission;private final FormalVerificationJobs.Job job;private final boolean send;private final JsonNode request,model;private final FormalInvocationPricing.Schedule price;private final String credential,credentialRevision,digest;
  private Verified(EnterpriseAccess.Admission a,FormalVerificationJobs.Job j,boolean send,JsonNode request,JsonNode model,FormalInvocationPricing.Schedule price,String credential,String credentialRevision,String digest){admission=a;job=j;this.send=send;this.request=request.deepCopy();this.model=model.deepCopy();this.price=price;this.credential=credential;this.credentialRevision=credentialRevision;this.digest=digest;}
  public JsonNode request(){return request.deepCopy();}public JsonNode model(){return model.deepCopy();}public FormalInvocationPricing.Schedule price(){return price;}public String credentialReferenceId(){return credential;}public String credentialRevision(){return credentialRevision;}public String authorizationSha256(){return digest;}
  public void requireCurrent()throws Exception{if(!digest.equals(require(admission,job,send).digest))throw new TenantAccessException(ErrorCode.SCOPE_STALE);}
 }
 Verified require(EnterpriseAccess.Admission a,FormalVerificationJobs.Job job,boolean send)throws Exception{
  if(!a.context().tenant_id().equals(job.tenant())||!TenantScope.requireCurrent().subjectId().equals(a.actorId()))fail();if(send&&!a.actorId().equals(job.actor()))throw new TenantAccessException(ErrorCode.ACCESS_DENIED);
  var request=schema.parse(job.request());var prior=schema.parse(job.dependencies());var model=models.read(a,job.model()).required("data");var definition=model.required("definition");if(!job.project().equals(model.required("project_id").textValue()))throw new TenantAccessException(ErrorCode.MODEL_POLICY_INCOMPLETE);
  if(!job.model().equals(model.required("current_model_revision").textValue())||!prior.required("model").required("content_sha256").equals(model.required("content_sha256"))||!schema.canonical(prior.required("model").required("definition")).equals(schema.canonical(definition)))throw new TenantAccessException(ErrorCode.REVISION_CONFLICT);
  var fixed=models.requireCurrentExternal(a,job.model(),"MODEL_VERIFICATION",job.project());var actual=(ModelConfigurationProtocol.Definition)fixed.definition();
  var intent=one(db.query("SELECT credential_reference_id,credential_revision,request_sha256,model_sha256 FROM runtime_connection_intent WHERE tenant_id=? AND verification_id=? AND created_by=? LIMIT 2",(r,n)->List.of(r.getString(1),r.getString(2),r.getString(3),r.getString(4)),job.tenant(),job.verification(),job.actor()));
  if(!intent.get(0).equals(actual.credential_reference_id())||!intent.get(1).equals(actual.credential_revision())||!intent.get(2).equals(job.requestHash())||!intent.get(3).equals(schema.hash(fixed)))fail();
  var credential=credentials.require(job.tenant(),intent.get(0),intent.get(1),actual.provider(),actual.base_url());
  var role=capabilities.require(a,basis(request.required("role_basis")),"ROLE",job.project(),"MODEL_VERIFICATION");var prompt=capabilities.require(a,basis(request.required("prompt_basis")),"PROMPT",job.project(),"MODEL_VERIFICATION");
  if(!schema.canonical(role.canonicalDefinition()).equals(schema.canonical(prior.required("role")))||!schema.canonical(prompt.canonicalDefinition()).equals(schema.canonical(prior.required("prompt"))))fail();
  var bases=new ArrayList<PermissionProtocol.Basis>();for(var b:request.required("rule_bases"))bases.add(basis(b));var checked=rules.require(a,job.project(),bases);if(!schema.canonical(checked.manifest().required("rules")).equals(schema.canonical(prior.required("rules").required("rules"))))throw new TenantAccessException(ErrorCode.SCOPE_STALE);
  var sources=inputs.requireCurrentReferences(a,request,actual.provider(),actual.region(),send?SourceReadProtocol.Use.MODEL_SEND:SourceReadProtocol.Use.REVIEW);
  var currentSources=new TreeMap<String,String>();sources.sources().forEach((id,value)->currentSources.put(id,value.rights().rightsRevision()));var savedSources=FormalInvocationSourceManifest.rights(prior.required("source_authorizations"));if(!savedSources.equals(currentSources))throw new TenantAccessException(ErrorCode.SCOPE_STALE);
  String priceAuth=originals.requireCurrentBasis(a,basis(definition.required("price_basis")),"MODEL_CONFIGURATION",job.project());String tokenizerAuth=originals.requireCurrentBasis(a,basis(request.required("tokenizer_basis")),"MODEL_CONFIGURATION",job.project());
  var price=prior.required("price");schema.require("PriceProfile",price);for(String key:List.of("provider","model_id","model_version","currency"))if(!definition.required(key).equals(price.required(key)))fail();
  if(send){var scope=new PermissionProtocol.Scope(job.tenant(),fixed.project_id(),"CONFIGURATION",fixed.config_id());resources.require(a,scope,"model.verify","MODEL_VERIFICATION");resources.require(a,scope,"model.send","MODEL_VERIFICATION");}
  credential.requireCurrent();role.requireUnchanged();prompt.requireUnchanged();checked.requireCurrent();
  String digest=schema.hash(Map.of("job",job.dependenciesHash(),"model",model.required("content_sha256"),"credential",credential.binding(),"sources",currentSources,"price_authorization",priceAuth,"tokenizer_authorization",tokenizerAuth,"actor",a.actorId(),"send",send));
  return new Verified(a,job,send,request,model,schema.price(definition.required("price_basis").required("version_id").textValue(),price),intent.get(0),intent.get(1),digest);
 }
 private static PermissionProtocol.Basis basis(JsonNode n){return new PermissionProtocol.Basis(n.required("version_id").textValue(),n.required("content_sha256").textValue());}private static <T>T one(List<T> rows){if(rows.size()!=1||rows.get(0)==null)fail();return rows.get(0);}private static void fail(){throw new TenantAccessException(ErrorCode.CONTENT_MISMATCH);}
}
